package it.carmine.streamplayer;

import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.ColorDrawable;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;
import java.util.*;import java.util.concurrent.*;

/** New LAB-only SC catalogue. The preserved 2.1.8 activities are not used or changed. */
public final class LabScProxyCatalogActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final ArrayList<VodSource.Title> titles=new ArrayList<>();private ArtworkStore artwork;private FrameLayout body;private TextView status;private EditText search;private String home,name;private volatile boolean closed;
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}private TextView text(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.WHITE);return t;}
 @Override public void onCreate(Bundle state){super.onCreate(state);try{home=VodSource.base(getIntent().getStringExtra("lab_url"));name=getIntent().getStringExtra("lab_name");}catch(Exception e){finish();return;}artwork=new ArtworkStore(this,true);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(12),dp(18),dp(12));root.setBackgroundColor(0xff10151c);setContentView(root);TextView heading=text("LAB PROXY · "+name,23);heading.setTextColor(0xff4fd4b1);root.addView(heading);status=text("Catalogo…",14);root.addView(status);LinearLayout commands=new LinearLayout(this);Button back=button("← Provider"),reload=button("Ricarica");commands.addView(back,new LinearLayout.LayoutParams(0,dp(48),1));commands.addView(reload,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(commands);back.setOnClickListener(v->finish());reload.setOnClickListener(v->load(""));search=new EditText(this);search.setSingleLine();search.setTextColor(Color.WHITE);search.setHintTextColor(0xffa0aab5);search.setHint("Cerca su "+name);search.setInputType(InputType.TYPE_CLASS_TEXT);root.addView(search);Button find=button("Cerca titolo");root.addView(find);find.setOnClickListener(v->load(search.getText().toString().trim()));body=new FrameLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));load("");}
 private void load(String query){status.setText(query.isEmpty()?"LAB · Caricamento locandine…":"LAB · Ricerca «"+query+"»…");worker.execute(()->{try{String html=query.isEmpty()?VodSource.fetch(home,home+"/"):VodSource.fetch(home+"/it/search?q="+VodSource.encode(query),home+"/");List<VodSource.Title> found=VodSource.catalog(VodSource.props(html),home);runOnUiThread(()->show(found));}catch(Exception e){runOnUiThread(()->status.setText("LAB · Catalogo: "+VodNetwork.error(e)));}});}
 private void show(List<VodSource.Title> found){if(closed)return;titles.clear();titles.addAll(found);body.removeAllViews();status.setText("LAB · "+found.size()+" titoli · resolver proxy separato");GridView grid=new GridView(this);grid.setNumColumns(3);grid.setHorizontalSpacing(dp(12));grid.setVerticalSpacing(dp(14));grid.setAdapter(new BaseAdapter(){public int getCount(){return titles.size();}public Object getItem(int i){return titles.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){VodSource.Title x=titles.get(i);LinearLayout card=new LinearLayout(LabScProxyCatalogActivity.this);card.setOrientation(1);card.setPadding(dp(4),dp(4),dp(4),dp(4));card.setBackgroundColor(0xff243343);ImageView poster=new ImageView(LabScProxyCatalogActivity.this);poster.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(poster,new LinearLayout.LayoutParams(-1,dp(178)));artwork.bind(poster,x.poster,new ColorDrawable(0xff354354));TextView label=text(x.name+(x.year.isEmpty()?"":" · "+x.year),14);label.setMaxLines(2);card.addView(label,new LinearLayout.LayoutParams(-1,dp(48)));return card;}});grid.setOnItemClickListener((p,v,index,id)->open(titles.get(index)));body.addView(grid);}
 private void open(VodSource.Title title){if(title.series()){status.setText("LAB proxy: selezione episodi non ancora collegata; usa il percorso SC conservato per le serie");return;}status.setText("LAB · Resolver VixCloud fresco · "+title.name);worker.execute(()->{try{VodSource.Stream stream=LabScResolver.resolve(home,title.id," ".trim());runOnUiThread(()->{if(closed)return;new AlertDialog.Builder(this).setTitle("VixCloud · proxy LAB").setMessage("Playlist ottenuta senza pre-consumarla. Il proxy manterrà Referer, Origin, cookie e Range su playlist, chiavi e segmenti.").setPositiveButton("Riproduci",(d,n)->startActivity(new Intent(this,LabScProxyPlayerActivity.class).putExtra("stream_url",stream.url).putExtra("stream_referer",stream.referer))).setNegativeButton("Annulla",null).show();});}catch(Exception e){runOnUiThread(()->status.setText("LAB · Resolver: "+VodNetwork.error(e)));}});}
 @Override protected void onDestroy(){closed=true;worker.shutdownNow();if(artwork!=null)artwork.close();super.onDestroy();}
}
